// Initialize random number generator
std::random_device rd;
std::mt19937 gen(rd());
std::normal_distribution<double> normal_dist(0.0, 1.0);

// Resize velocities vector if needed
if (velocities.size() != masses.size()) {
    velocities.resize(masses.size());
}

// Generate initial velocities from Maxwell-Boltzmann distribution
for (size_t i = 0; i < velocities.size(); ++i) {
    double sigma = std::sqrt(temperature / masses[i]);
    velocities[i].x = normal_dist(gen) * sigma;
    velocities[i].y = normal_dist(gen) * sigma;
    velocities[i].z = normal_dist(gen) * sigma;
}

// Calculate center of mass velocity
vec3 com_velocity(0.0, 0.0, 0.0);
double total_mass = 0.0;

for (size_t i = 0; i < masses.size(); ++i) {
    com_velocity.x += masses[i] * velocities[i].x;
    com_velocity.y += masses[i] * velocities[i].y;
    com_velocity.z += masses[i] * velocities[i].z;
    total_mass += masses[i];
}

if (total_mass > 0) {
    com_velocity.x /= total_mass;
    com_velocity.y /= total_mass;
    com_velocity.z /= total_mass;
}

// Subtract center of mass velocity from all particles
for (size_t i = 0; i < velocities.size(); ++i) {
    velocities[i].x -= com_velocity.x;
    velocities[i].y -= com_velocity.y;
    velocities[i].z -= com_velocity.z;
}
// END_CODE

